def max_product(num_str: str, N: int, K: int) -> int:
    # Ensure N matches the actual length of the input string
    if N != len(num_str):
        N = len(num_str)
    # Cannot have more cuts than positions available
    K = min(K, N - 1)
    # Precompute integer values for all substrings num_str[i:j]
    sub = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + int(num_str[j - 1])
            sub[i][j] = val
    # dp[i][k] = maximum product for prefix of length i with k cuts (k+1 numbers)
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        dp[i][0] = sub[0][i]
    for k in range(1, K + 1):
        for i in range(k + 1, N + 1):
            best = 0
            for j in range(k, i):
                prod = dp[j][k - 1] * sub[j][i]
                if prod > best:
                    best = prod
            dp[i][k] = best
    return dp[N][K]

