def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Convert a list of polynomial coefficients into a formatted string representation.

    :param n: The highest degree of the polynomial.
    :param coeffs: A list of coefficients, starting with the coefficient of the highest degree term.
    :return: The string representation of the polynomial.
    """
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        # Determine sign
        if not terms:
            sign = '' if coeff > 0 else '-'
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Coefficient part
        if abs_coeff == 1 and degree != 0:
            coeff_part = ''
        else:
            coeff_part = str(abs_coeff)

        # Variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = f"{sign}{coeff_part}{var_part}"
        terms.append(term)

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    Parameters:
    encoded (str): The encoded string corresponding to the original string.
    original (str): The original string corresponding to the encoded string.
    message (str): The encrypted message to decode.

    Returns:
    str: The decoded message, or "Failed" if the decoding cannot be performed.
    """
    if len(encoded) != len(original):
        return "Failed"

    enc_map = {}
    rev_map = {}
    for e, o in zip(encoded, original):
        if e in enc_map:
            if enc_map[e] != o:
                return "Failed"          # Contradictory mapping
        else:
            enc_map[e] = o
            # Ensure bijection: two encoded letters cannot map to same original
            if o in rev_map and rev_map[o] != e:
                return "Failed"
            rev_map[o] = e

    # Must have a full substitution for all 26 uppercase letters
    if len(enc_map) < 26:
        return "Failed"

    result = []
    for ch in message:
        if ch not in enc_map:
            return "Failed"  # message contains an unknown letter
        result.append(enc_map[ch])

    return "".join(result)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    if A == B:
        return 0
    visited = {A}
    queue = [(A, 0)]
    while queue:
        s, step = queue.pop(0)
        if step >= 10:
            continue
        for src, tgt in rules:
            start = 0
            while True:
                idx = s.find(src, start)
                if idx == -1:
                    break
                new_s = s[:idx] + tgt + s[idx+len(src):]
                if new_s == B:
                    return step + 1
                if new_s not in visited:
                    visited.add(new_s)
                    queue.append((new_s, step+1))
                start = idx + 1
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize scenario for case-insensitive comparison
    scenario_upper = scenario.upper()

    # Helper to determine truth of a statement
    def is_statement_true(participant: str, statement: str) -> bool:
        stmt = statement.strip().lower()

        # Ignore statements about the day of the week
        for day in days_of_week:
            if day.lower() in stmt:
                return None  # signal that this statement should be ignored

        # Match simple patterns
        if stmt.startswith("i am guilty"):
            return participant.upper() == scenario_upper
        if stmt.startswith("i am not guilty"):
            return participant.upper() != scenario_upper

        # Match patterns like "<NAME> is guilty." or "<NAME> is not guilty."
        if " is guilty" in stmt:
            name = stmt.split(" is guilty")[0].strip().upper()
            return name == scenario_upper
        if " is not guilty" in stmt:
            name = stmt.split(" is not guilty")[0].strip().upper()
            return name != scenario_upper

        # If we cannot interpret the statement, treat it as neutral (ignored)
        return None

    for participant, p_statements in statements.items():
        for st in p_statements:
            truth_val = is_statement_true(participant, st)
            if truth_val is None:
                # Statement is ignored (day reference or unrecognizable)
                continue

            if participant in liar_count:
                if truth_val is True:
                    return False  # liar said a true statement
            else:
                if truth_val is False:
                    return False  # truth-teller said a false statement

    return True

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        total = 0
        for j in range(i):
            total += catalan[j] * catalan[i - 1 - j]
        catalan[i] = total
    return catalan[n]
